document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll(".service-manifesto-section__inner");if(!e.length)return;if(window.matchMedia("(prefers-reduced-motion: reduce)").matches||"undefined"==typeof IntersectionObserver)return void e.forEach(e=>e.classList.add("is-visible"));const t=new IntersectionObserver(e=>{e.forEach(e=>{e.target.classList.toggle("is-visible",e.isIntersecting)})},{threshold:.3});requestAnimationFrame(()=>{requestAnimationFrame(()=>{e.forEach(e=>t.observe(e))})})});